#include <stdio.h>
#include <string.h>

#define MAXLEN 65   /* 0x41 in the original binary */

int main(int argc, char **argv)
{
    /* Argument check – the original program expects exactly two arguments */
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    const char *pattern = argv[1];
    const char *text    = argv[2];

    /* Length limits – the binary aborts with USAGE if either string is too long */
    size_t plen = strlen(pattern);
    size_t tlen = strlen(text);
    if (plen >= MAXLEN || tlen >= MAXLEN) {
        puts("USAGE");
        return 0;
    }

    /* DP table: (plen+1) x (tlen+1).  The original code used a flat array of
       4‑byte entries, but a simple 2‑D array is clearer. */
    int dp[MAXLEN][MAXLEN] = {0};

    dp[0][0] = 1;                     /* empty pattern matches empty text */

    /* First column: pattern vs empty text.
       Only a leading sequence of '*' can match the empty string. */
    for (size_t i = 1; i <= plen; ++i) {
        if (pattern[i - 1] == '*')
            dp[i][0] = dp[i - 1][0];
        else
            dp[i][0] = 0;
    }

    /* Fill the rest of the table */
    for (size_t i = 1; i <= plen; ++i) {
        for (size_t j = 1; j <= tlen; ++j) {
            char pc = pattern[i - 1];
            char tc = text[j - 1];

            if (pc == '*') {
                /* '*' matches zero characters (dp[i‑1][j]) or one more character (dp[i][j‑1]) */
                dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
            } else if (pc == '?' || pc == tc) {
                /* '?' matches any single character; otherwise characters must be equal */
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = 0;
            }
        }
    }

    puts(dp[plen][tlen] ? "MATCH" : "NO_MATCH");
    return 0;
}
